import numpy as np

def kernel(a, b):
    M, K = a.shape
    K2, N = b.shape
    assert K == K2, "Inconsistent dimensions for matrix multiplication"
    result = np.zeros((M, N), dtype=np.float32)
    tile_size_a = 128
    tile_size_b = 512

    for i in range(0, M, tile_size_a):
        for j in range(0, N, tile_size_b):
            # Cast the relevant slices to float64 for higher precision
            a_slice = a[i:min(i + tile_size_a, M), :].astype(np.float64)
            b_slice = b[:, j:min(j + tile_size_b, N)].astype(np.float64)

            for ii in range(i, min(i + tile_size_a, M)):
                for jj in range(j, min(j + tile_size_b, N)):
                    val = 0.0
                    for k in range(K):
                        val += a_slice[ii - i, k] * b_slice[k, jj - j]
                    result[ii, jj] = np.float32(val)
    return result
